fun rwRulesSeqStx x =>
  have lbrak := rwRulesSeqStx[0];
  have rules := rwRulesSeqStx[1].getArgs;
  do
  Lean.Elab.Tactic.withTacticInfoContext lbrak (pure ())
  have numRules : ℕ := (rules.size + 1) / 2
  forIn [:numRules] PUnit.unit fun i __s =>
      have rule := rules[i * 2]!;
      have sep := rules.getD (i * 2 + 1) Lean.Syntax.missing;
      do
      Lean.Elab.Tactic.withTacticInfoContext (Lean.mkNullNode #[rule, sep])
          (Lean.withRef rule
            (have symm := !rule[0].isNone;
            have term := rule[1];
            x symm term))
      pure (ForInStep.yield PUnit.unit)
  pure ()

